import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s<>"]+|www\.[^\s<>"]+'
    urls = re.findall(url_pattern, myString)
    domains = {}
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc if parsed.netloc else parsed.path.split('/')[0]
        if domain.startswith('www.'):
            domain = domain[4:]
        domains[domain] = None
    for domain in domains:
        try:
            response = requests.get(f'http://ip-api.com/json/{domain}?fields=status,message,country,regionName,city,lat,lon,isp,org,as,query&key={API_KEY}')
            data = response.json()
            domains[domain] = data
        except:
            pass
    return domains

